@PostMapping("/checkout/confirm")
public String confirmOrder(@RequestParam Long orderId) {
    Order order = orderRepo.findById(orderId).orElseThrow();
    order.setStatus(OrderStatus.CONFIRMED);
    orderRepo.save(order);
    paymentService.charge(order.getTotal());
    return "Order confirmed";
}

@PostMapping("/order/ship")
public void shipOrder(@PathVariable Long orderId, @RequestParam String status) {
    Order order = orderRepo.findById(orderId).get();
    order.setStatus(OrderStatus.valueOf(status));  // 客户端控制状态!
    orderRepo.save(order);
}

@app.post("/checkout/step/{step_id}")
async def process_step(step_id: int, order_id: int):
    order = await Order.get(id=order_id)
    order.current_step = step_id  # 客户端可跳步
    await order.save()
    return {"next_step": step_id + 1}

app.post('/checkout', async (req, res) => {
    const { orderId, step, couponCode } = req.body;
    const order = await Order.findByPk(orderId);

    if (step === 'payment') {
        // 可被直接调用，跳过地址确认步骤
        await processPayment(order, req.body.paymentInfo);
        order.status = 'paid';
    }
    await order.save();
    res.json(order);
});

